using PX.Data;
using PX.Data.BQL;

namespace PX.Objects.GL.DAC
{
    public class OrganizationExt : PXCacheExtension<Organization>
    {
        public static bool IsActive() => true;

        #region UsrFACompanyCode
        [PXDBString(2, IsUnicode = true, InputMask = ">CC")]
        [PXUIField(DisplayName = "FA Company Code")]
        public virtual string UsrFACompanyCode { get; set; }
        public abstract class usrFACompanyCode : BqlString.Field<usrFACompanyCode> { }
        #endregion
    }
}
